 * $style: 'badge' = دايرة ملونة وجواها الشعار أبيض (للأفاتار)، 'plain' = الشعار بلونه
 */
function platform_icon(string $platform, string $class = 'w-4 h-4', string $style = 'plain'): string
{
    $icons = platform_icons();
    if (!isset($icons[$platform])) {
        return '';
    }
    [$color, $path] = $icons[$platform];
    $title = e(platform_label($platform));
    // الشعارات السودا (X، تيك توك، ثريدز) بتاخد لون النص عشان تبان في الوضع الداكن
    $dark = in_array(strtolower($color), ['#000000'], true);
    if ($style === 'badge') {
        $bg = $dark ? 'background:#111' : 'background:' . $color;
        $fg = $platform === 'snapchat' ? '#111' : '#fff';
        return '<span class="inline-flex items-center justify-center rounded-full ring-2 ring-white shrink-0 ' . $class . '" style="' . $bg . '" title="' . $title . '">'
            . '<svg viewBox="0 0 24 24" class="w-[60%] h-[60%]" fill="' . $fg . '" aria-hidden="true"><path d="' . $path . '"/></svg></span>';
    }
    return '<svg viewBox="0 0 24 24" class="shrink-0 ' . $class . ($dark ? ' text-ink-900' : '') . '" fill="' . ($dark ? 'currentColor' : $color) . '" role="img" aria-label="' . $title . '"><title>' . $title . '</title><path d="' . $path . '"/></svg>';
}

/** أفاتار بشارة المنصة في الركن */
function avatar_with_platform(?string $src, string $name, string $platform, string $size = 'w-11 h-11'): string
{
    return '<span class="relative inline-block shrink-0">' . avatar($src, $name, $size)
        . '<span class="absolute -bottom-0.5 -end-0.5">' . platform_icon($platform, 'w-[18px] h-[18px]', 'badge') . '</span></span>';
}
